def transform(grid):
    # The uniform row separates two noisy panels. Their shared color is the
    # output background; the top panel's other color becomes the marked cells.
    sep = next(i for i, row in enumerate(grid) if len(set(row)) == 1)
    top, bottom = grid[:sep], grid[sep + 1:]

    top_colors = {x for row in top for x in row}
    bottom_colors = {x for row in bottom for x in row}
    shared = top_colors & bottom_colors
    bg = next(iter(shared)) if shared else max(
        top_colors, key=lambda c: sum(x == c for row in top for x in row)
    )

    return [[bg if x == bg else 3 for x in row] for row in top]
