    from collections import Counter

    def bg(panel):
        return Counter(x for row in panel for x in row).most_common(1)[0][0]

    top_bg, bottom_bg = bg(top), bg(bottom)
    out = []
    for r, row in enumerate(top):
        out.append([
            3 if row[c] != top_bg or bottom[r][c] != bottom_bg else top_bg
            for c in range(len(row))
        ])
