def transform(grid):
    from collections import Counter

    # Find the separator row: its color is absent from both adjoining panels
    # except for the separator itself.
    candidates = []
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            color = row[0]
            above = {x for r in grid[:i] for x in r}
            below = {x for r in grid[i + 1:] for x in r}
            if color not in above and color not in below:
                candidates.append(i)
    sep = candidates[0] if candidates else next(
        i for i, row in enumerate(grid) if len(set(row)) == 1
    )

    top = grid[:sep]
    counts = Counter(x for row in top for x in row)
    background = counts.most_common(1)[0][0]
    return [[background if x == background else 3 for x in row] for row in top]
